message:
{# --- Setup & helpers --- #}
{% set url = \"https://crafted.retail.lightspeed.app/register/closure/summary/\" ~ (doc.source_id or doc.name) %}
{% macro money(v) -%}{{ \"%.2f\"|format((v or 0)|float) }}{%- endmacro %}

{# --- Scan rows to get totals and count --- #}
{% set ns = namespace(total=0.0, count=0) %}
{% for row in (doc.payment_counts or []) %}
  {% set d = (row.discrepancy is defined and row.discrepancy is not none)
              and (row.discrepancy|float)
              or ((row.payments_total|float) - (row.close_total|float)) %}
  {% if d != 0 %}
    {% set ns.total = ns.total + d %}
    {% set ns.count = ns.count + 1 %}
  {% endif %}
{% endfor %}

{# --- Message --- #}
{% if ns.count > 0 %}
<br>**Register closure discrepancies detected**
<br>- Register: {{ doc.register_name or \"Unknown Register\" }} (Outlet: {{ doc.outlet_name or \"Unknown Outlet\" }})
<br>- Period: {{ doc.register_open_time or \"N/A\" }} → {{ doc.register_close_time or \"N/A\" }}
<br>- Discrepancies: {{ ns.count }} (total {{ money(ns.total) }})

<br>Please review the closure details here:
{{ url }}
<br>**Breakdown**
{% for row in (doc.payment_counts or []) %}
  {% set d = (row.discrepancy is defined and row.discrepancy is not none)
              and (row.discrepancy|float)
              or ((row.payments_total|float) - (row.close_total|float)) %}
  {% if d != 0 %}
<br>- {{ row.payment_type_name or \"Unknown Method\" }} → payments {{ money(row.payments_total) }}, close {{ money(row.close_total) }}, **Δ {{ money(d) }}**
  {% endif %}
{% endfor %}

{% else %}
<br>**Register closure balanced**
<br>- Register: {{ doc.register_name or \"Unknown Register\" }} (Outlet: {{ doc.outlet_name or \"Unknown Outlet\" }})
<br>- Period: {{ doc.register_open_time or \"N/A\" }} → {{ doc.register_close_time or \"N/A\" }}

<br>No discrepancies were found. Full report: {{ url }}
{% endif %}
